CREATE OR REPLACE FUNCTION public.validate_portal_record() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE p public.portal_records; BEGIN IF length(new.title)<2 OR length(new.title)>200 THEN RAISE EXCEPTION 'Invalid title'; END IF; IF new.end_date<new.start_date THEN RAISE EXCEPTION 'Invalid dates'; END IF; IF new.kind='complaint' AND new.status NOT IN ('nouvelle','en cours de traitement','en attente','clôturée') THEN RAISE EXCEPTION 'Invalid complaint status'; END IF; IF new.kind='invoice' AND new.status NOT IN ('brouillon','émise','annulée') THEN RAISE EXCEPTION 'Settlement is derived from validated payments'; END IF; IF new.kind='payment' AND new.status NOT IN ('en attente','validé','rejeté') THEN RAISE EXCEPTION 'Invalid payment status'; END IF; IF new.kind='payment' THEN IF NOT public.portal_can('finance') THEN RAISE EXCEPTION 'Forbidden'; END IF; SELECT * INTO p FROM public.portal_records WHERE id=new.parent_id FOR UPDATE; IF p.id IS NULL OR p.kind NOT IN ('invoice','mission') OR new.owner_id IS DISTINCT FROM p.owner_id OR new.provider_id IS DISTINCT FROM p.provider_id THEN RAISE EXCEPTION 'Invalid payment relationship'; END IF; IF new.amount<=0 THEN RAISE EXCEPTION 'Payment must be positive'; END IF; IF TG_OP='UPDATE' AND old.status='validé' THEN RAISE EXCEPTION 'Validated payments are immutable'; END IF; IF new.status='validé' AND new.amount+(SELECT coalesce(sum(amount),0) FROM public.portal_records WHERE parent_id=new.parent_id AND kind='payment' AND status='validé' AND id<>new.id)>p.amount THEN RAISE EXCEPTION 'Payment exceeds balance'; END IF; END IF; IF new.parent_id IS NOT NULL THEN SELECT * INTO p FROM public.portal_records WHERE id=new.parent_id; IF p.id IS NULL OR new.owner_id IS DISTINCT FROM p.owner_id OR (new.kind IN ('report','payment') AND new.provider_id IS DISTINCT FROM p.provider_id) THEN RAISE EXCEPTION 'Invalid tenant relationship'; END IF; END IF; IF NOT public.portal_record_staff(new.kind) THEN IF new.kind='complaint' AND (new.attributes - ARRAY['description','category'])<>'{}'::jsonb THEN RAISE EXCEPTION 'Client cannot write staff response'; END IF; IF new.kind='report' AND (new.attributes - ARRAY['description','incident','difficulties'])<>'{}'::jsonb THEN RAISE EXCEPTION 'Provider cannot write validation'; END IF; END IF; new.updated_at=now(); RETURN new; END $$;
CREATE TRIGGER portal_record_validation BEFORE INSERT OR UPDATE ON public.portal_records FOR EACH ROW EXECUTE FUNCTION public.validate_portal_record();
CREATE OR REPLACE FUNCTION public.provider_mission_action(mission_id uuid, action text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.portal_records; next_status text; BEGIN SELECT * INTO m FROM public.portal_records WHERE id=mission_id FOR UPDATE; IF auth.uid() IS NULL OR m.kind<>'mission' OR m.provider_id IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Forbidden'; END IF; next_status=CASE WHEN m.status='attribuée' AND action='accept' THEN 'acceptée' WHEN m.status='attribuée' AND action='refuse' THEN 'refusée' WHEN m.status='acceptée' AND action='start' THEN 'en cours' WHEN m.status='en cours' AND action='finish' THEN 'en attente de validation' END; IF next_status IS NULL THEN RAISE EXCEPTION 'Invalid transition'; END IF; UPDATE public.portal_records SET status=next_status,attributes=attributes||jsonb_build_object(action||'_at',now()) WHERE id=mission_id; END $$;
REVOKE ALL ON FUNCTION public.provider_mission_action(uuid,text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.provider_mission_action(uuid,text) TO authenticated;
CREATE TABLE public.portal_documents (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), record_id uuid NOT NULL REFERENCES public.portal_records(id), name text NOT NULL, storage_path text NOT NULL UNIQUE, uploaded_by uuid NOT NULL DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT ON public.portal_documents TO authenticated;
GRANT ALL ON public.portal_documents TO service_role;
ALTER TABLE public.portal_documents ENABLE ROW LEVEL SECURITY;
CREATE POLICY documents_read ON public.portal_documents FOR SELECT TO authenticated USING(EXISTS(SELECT 1 FROM public.portal_records WHERE id=record_id));
CREATE POLICY documents_insert ON public.portal_documents FOR INSERT TO authenticated WITH CHECK(uploaded_by=auth.uid() AND split_part(storage_path,'/',1)=record_id::text AND EXISTS(SELECT 1 FROM public.portal_records r WHERE r.id=record_id AND (public.portal_record_staff(r.kind) OR (r.kind='complaint' AND r.owner_id=auth.uid() AND r.status='nouvelle') OR (r.kind='report' AND r.provider_id=auth.uid() AND r.status='soumis'))));
CREATE POLICY portal_storage_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='portal-documents' AND EXISTS(SELECT 1 FROM public.portal_documents WHERE storage_path=name));
CREATE POLICY portal_storage_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='portal-documents' AND EXISTS(SELECT 1 FROM public.portal_records r WHERE r.id::text=split_part(name,'/',1) AND (public.portal_record_staff(r.kind) OR (r.kind='complaint' AND r.owner_id=auth.uid() AND r.status='nouvelle') OR (r.kind='report' AND r.provider_id=auth.uid() AND r.status='soumis'))));